WITH with_latest AS (SELECT s.*, x.brand FROM suppliers s LEFT JOIN LATERAL (SELECT c.brand FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT city, CASE WHEN rating >= 3.9 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, PERCENTILE_APPROX(rating, 0.95) AS rating_p95, SUM(rating) AS total_rating, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN brand = 'Globex' THEN 1 END), 0), 2) AS rating_per_globex, SUM(rating) FILTER (WHERE brand = 'Globex') AS globex_total_rating, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, GROUPING(city) AS gid FROM with_latest GROUP BY ROLLUP (city, CASE WHEN rating >= 3.9 THEN 'HIGH' ELSE 'LOW' END) HAVING COUNT(CASE WHEN country = 'US' THEN 1 END) > 1;
